import { createFileRoute, useParams } from '@tanstack/react-router';
import EventViewPage from '@/pages/events/EventViewPage';
import { PageTabs } from '@/components/PageTabs';
import { EventTabs } from '@/constants/Routes';
import { useIsAuthenticated } from '@/contexts/AuthProvider';
import { IsTokenValid } from '@/utils/token';

/**
 * Canonical event page: `/events/{id}` — one URL for everyone.
 *
 * An event is a publicly shareable resource (`GET /events/{id}` is `[AllowAnonymous]`),
 * so this sits outside the `_auth` guard: whatever a member copies from their address bar
 * has to work for whoever they send it to. The rest of `/events/*` (create, all, edit)
 * stays private under `_auth`; the router ranks those static segments above this dynamic
 * param, and the API additionally refuses to mint events with those ids as slugs.
 *
 * The page adapts rather than forking: members get the event tabs and their registration
 * details, anonymous visitors get the event plus the inline sign-in / register stepper.
 */
export const Route = createFileRoute('/_public/events/$id')({
  component: function Page() {
    const { id } = useParams({ from: '/_public/events/$id' });
    const contextAuthenticated = useIsAuthenticated();
    // IsTokenValid() covers the moment right after the inline stepper signs someone in,
    // before the auth context has been republished.
    const isAuthenticated = contextAuthenticated || IsTokenValid();

    return (
      <>
        {isAuthenticated && <PageTabs tabs={EventTabs} />}
        <EventViewPage eventId={id} />
      </>
    );
  },
});
